// Import of required libraries
import { test, expect, SkyrampClient, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createLink, createBulkArchiveJob, deleteLink, deleteCollection } from './skyrampUtils';

// An id that names no link at all, so it is never owned by the caller.
const UNOWNED_LINK_ID = 999999999;

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const linkName = "Bulk archive ownership link";
    const linkUrl = uniqueSuffix("https://example.com/bulk-archive-ownership");
    const collectionName = uniqueSuffix("Bulk Archive Ownership");

    const linksPostResponse = await createLink(client, headers, linkName, linkUrl, collectionName);

    const linkId = getResponseValue(linksPostResponse, "response.id");
    const collectionId = getResponseValue(linksPostResponse, "response.collection.id");
    expect(linkId, 'link id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe(linkUrl);
    expect(getResponseValue(linksPostResponse, "response.collection.ownerId"), 'collection owner').toBeGreaterThan(0);

    // An id the caller does not own is rejected.
    const bulkArchivePostResponse = await createBulkArchiveJob(client, headers, [UNOWNED_LINK_ID], 403);
    expect(bulkArchivePostResponse.statusCode, 'status code').toBe(403);
    expect(getResponseValue(bulkArchivePostResponse, "response"), 'rejection message').toBe("One or more links are not accessible.");
    expect(getResponseValue(bulkArchivePostResponse, "response.jobId"), 'no job id').toBeNull();
    expect(getResponseValue(bulkArchivePostResponse, "response.status"), 'no job status').toBeNull();

    // One unowned id among owned ids rejects the whole batch.
    const bulkArchivePost1Response = await createBulkArchiveJob(client, headers, [linkId, UNOWNED_LINK_ID], 403);
    expect(bulkArchivePost1Response.statusCode, 'status code').toBe(403);
    expect(getResponseValue(bulkArchivePost1Response, "response"), 'rejection message').toBe("One or more links are not accessible.");
    expect(getResponseValue(bulkArchivePost1Response, "response.jobId"), 'no job id').toBeNull();
    expect(getResponseValue(bulkArchivePost1Response, "response.status"), 'no job status').toBeNull();

    // The PR reserves 403 for an id that is not owned: "Returns 403 if any linkId is not owned by
    // the caller." A repeated id the caller DOES own contains no such id, so the batch is accepted.
    const bulkArchivePost2Response = await createBulkArchiveJob(client, headers, [linkId, linkId], 202);
    expect(bulkArchivePost2Response.statusCode, 'status code').toBe(202);
    expect(getResponseValue(bulkArchivePost2Response, "response.status"), 'job status').toBe("queued");
    expect(getResponseValue(bulkArchivePost2Response, "response.jobId"), 'job id').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);

    const linksLinksDeleteResponse = await deleteLink(client, headers, linkId);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link id').toBe(linkId);

    const collectionsDeleteResponse = await deleteCollection(client, headers, collectionId);
    expect(getResponseValue(collectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(collectionId);
});
